package com.ryanjei.orushio.pve.map;import static org.junit.jupiter.api.Assertions.*;import java.nio.file.*;import java.util.*;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;
class SetupMarkerPersistenceTest{@TempDir Path temp;
 @Test void stableMarkerを保存再読込する(){YamlMapProfileRepository repository=new YamlMapProfileRepository(temp);MapProfile profile=MapProfileTest.complete("map-a");SetupMarker marker=new SetupMarker(UUID.randomUUID(),SetupMarkerType.FINAL_GATE,new BlockPoint(4,65,6,0,0),false);MapProfile value=new MapProfile(profile.mapId(),profile.displayName(),false,profile.templateDirectory(),profile.points(),profile.areas(),profile.createdAt(),profile.spawnMarkers(),List.of(marker));repository.save(value);assertEquals(marker,repository.find(profile.mapId()).orElseThrow().setupMarkers().getFirst());}
 @Test void 旧pointはSetupMarkerへ自動移行せず新仕様で再設定を要求する()throws Exception{YamlMapProfileRepository repository=new YamlMapProfileRepository(temp);MapProfile profile=MapProfileTest.complete("map-a");repository.save(profile);Path file=temp.resolve("map-a/profile.yml");String yaml=Files.readString(file);yaml=yaml.replaceFirst("setupMarkers:.*\\R","points.normalCoreCandidates: \"1,64,1,0.0,0.0;2,64,1,0.0,0.0;3,64,1,0.0,0.0\"\n");Files.writeString(file,yaml);MapProfile loaded=repository.find(profile.mapId()).orElseThrow();assertEquals(0,loaded.enabledSetupMarkers(SetupMarkerType.NORMAL_CORE).size());assertFalse(loaded.setupComplete());assertTrue(Files.readString(file).contains("points.normalCoreCandidates"));}
}
